package main

import (
	"context"
	"fmt"

	"github.com/example/openai"
	"github.com/example/openai/option"
)

func main() {
	client := openai.NewClient(
		option.WithAPIKey("My API Key"),
	)
	result, err := client.Realtime.Translations.ClientSecrets.New(
		context.TODO(),
		openai.RealtimeTranslationClientSecretNewParams{
			ExpiresAfter: openai.RealtimeTranslationClientSecretCreateRequestExpiresAfter{Anchor: "created_at", Seconds: 600},
			Session: openai.RealtimeTranslationSessionCreateRequest{Model: "string", Audio: openai.RealtimeTranslationSessionCreateRequestAudio{Input: openai.RealtimeTranslationSessionCreateRequestAudioInput{Transcription: openai.RealtimeTranslationSessionCreateRequestAudioInputTranscription{Model: "string"}, NoiseReduction: openai.RealtimeTranslationSessionCreateRequestAudioInputNoiseReduction{Type: openai.NoiseReductionTypeNearField}}, Output: openai.RealtimeTranslationSessionCreateRequestAudioOutput{Language: "string"}}},
		},
	)
	if err != nil {
		panic(err.Error())
	}
	fmt.Printf("%+v\n", result)
}
